	e.m.RLock()
	newModel, err := e.loadPolicyFromAdapter(e.model)
	e.m.RUnlock()
	if err != nil {
		return err
	}
	e.m.Lock()
	err = e.applyModifiedModel(newModel)
	e.m.Unlock()
	if err != nil {
		return err
	}
	return nil
}

