   /**
    * Add a new entry to ACL config
    *
    * @param string $scope
    * @param string $authUser
    * @param int    $level see also inc/auth.php
    * @throws RemoteAccessDeniedException
    * @return bool
    */
   public function addAcl($scope, $authUser, $level){
       if(!auth_isadmin()) {
           throw new RemoteAccessDeniedException('You are not allowed to access ACLs, superuser permission is required', 114);
       }

       /** @var admin_plugin_acl $apa */
       $apa = plugin_load('admin', 'acl');
       return $apa->_acl_add($scope, $authUser, $level);
   }

   /**
    * Remove an entry from ACL config
    *
    * @param string $scope
    * @param string $authUser
    * @throws RemoteAccessDeniedException
    * @return bool
    */
   public function delAcl($scope, $authUser){
       if(!auth_isadmin()) {
           throw new RemoteAccessDeniedException('You are not allowed to access ACLs, superuser permission is required', 114);
       }

       /** @var admin_plugin_acl $apa */
       $apa = plugin_load('admin', 'acl');
       return $apa->_acl_del($scope, $authUser);
   }

