    {
        if ($authUser->userRole !== 'student') {
            return back()->withErrors(['error' => 'Invalid authUser userRole.']);
        }

        $authUser->update(['approval_status' => 'approved']);

        return back()->with('success', "{$authUser->name} has been approved and can now log in.");
    }

