    {
        if ($authUser->userRole !== 'student') {
            return back()->withErrors(['error' => 'Invalid authUser userRole.']);
        }

        $authUser->update(['approval_status' => 'rejected']);

        return back()->with('success', "{$authUser->name} has been rejected.");
    }

