    {
        if ($authUser->userRole !== 'student') {
            return back()->withErrors(['error' => 'Invalid authUser userRole.']);
        }

        $authUser->update(['approval_status' => 'pending']);

        return back()->with('success', "{$authUser->name} status has been reset to pending.");
    }
