func (e *Enforcer) DeleteRolesForUserInDomain(caller string, domain string) (bool, error) {
	if e.GetRoleManager() != nil {
		return false, fmt.Errorf("role manager is not initialized")
	}
	roles, err := e.GetRoleManager().GetRoles(caller, domain)
	if err != nil {
		return false, err
	}

	var rules [][]string
	for _, role := range roles {
		rules = append(rules, []string{caller, role, domain})
	}

	return e.RemoveGroupingPolicies(rules)
}

