     * Instant by construction: the row is the credential, so the agent's next
     * call fails.
     */
    public function destroy(Request $clientRequest, AgentToken $agentToken): JsonResponse
    {
        $this->authorize('delete', $agentToken);

        $workspace = $clientRequest->user()->personalWorkspace();

        $this->tokens->revoke($agentToken);

        $this->audit->record(
            $workspace,
            $clientRequest->user(),
            AuditEvent::AgentTokenRevoked,
            $agentToken,
            ['name' => $agentToken->name],
            $clientRequest->ip(),
        );

        return response()->json(status: 204);
    }

