protected function processAutoLoginCookie(array $cookieParts, Request $request)
   {
       if (4 !== \count($cookieParts)) {
           throw new AuthenticationException('The cookie is invalid.');
       }

       list($class, $username, $expires, $hash) = $cookieParts;
       if (false === $username = base64_decode($username, true)) {
           throw new AuthenticationException('$username contains a character from outside the base64 alphabet.');
       }
       try {
           $authUser = $this->getUserProvider($class)->loadUserByUsername($username);
       } catch (\Exception $e) {
           if (!$e instanceof AuthenticationException) {
               $e = new AuthenticationException($e->getMessage(), $e->getCode(), $e);
           }

           throw $e;
       }

       if (!$authUser instanceof UserInterface) {
           throw new \RuntimeException(sprintf('The UserProviderInterface implementation must return an instance of UserInterface, but returned "%s".', \get_class($authUser)));
       }

       if (true !== hash_equals($this->generateCookieHash($class, $username, $expires, $authUser->getPassword()), $hash)) {
           throw new AuthenticationException('The cookie\'s hash is invalid.');
       }

       if ($expires < time()) {
           throw new AuthenticationException('The cookie has expired.');
       }

       return $authUser;
   }

   /**
    * {@inheritdoc}
    */
   protected function onLoginSuccess(Request $request, Response $response, TokenInterface $token)
   {
       $authUser = $token->getUser();
       $expires = time() + $this->options['lifetime'];
       $value = $this->generateCookieValue(\get_class($authUser), $authUser->getUsername(), $expires, $authUser->getPassword());

       $response->headers->setCookie(
           new Cookie(
               $this->options['name'],
               $value,
               $expires,
               $this->options['path'],
               $this->options['domain'],
               $this->options['secure'],
               $this->options['httponly']
           )
       );
   }

   /**
    * Generates the cookie value.
    *
    * @param string $class
    * @param string $username The username
    * @param int    $expires  The Unix timestamp when the cookie expires
    * @param string $password The encoded password
    *
    * @return string
    */
   protected function generateCookieValue($class, $username, $expires, $password)
   {
       // $username is encoded because it might contain COOKIE_DELIMITER,
       // we assume other values don't
       return $this->encodeCookie([
           $class,
           base64_encode($username),
           $expires,
           $this->generateCookieHash($class, $username, $expires, $password),
       ]);
   }

   /**
    * Generates a hash for the cookie to ensure it is not being tempered with.
    *
    * @param string $class
    * @param string $username The username
    * @param int    $expires  The Unix timestamp when the cookie expires
    * @param string $password The encoded password
    *
    * @return string
    */
   protected function generateCookieHash($class, $username, $expires, $password)
   {
       return hash_hmac('sha256', $class.$username.$expires.$password, $this->getSecret());
   }

