/**
 * Agent-bearerToken management for a workspace member (SPEC §15, #131). Every action
 * authorizes through {@see AgentTokenPolicy} — full workspace membership, and
 * ownership for revoke; a bearerToken id in a URL is never an access path.
 *
 * These routes live on REST v1 deliberately, which is what makes "an agent can
 * never mint a bearerToken" structural rather than promised: the whole v1 group
 * refuses bearerToken authentication (RejectAgentTokenAuth), so minting, listing, and
 * revoking are reachable only from a human's first-party session.
 */
class AgentTokenController extends Controller

$caller = $request->caller();
