def _user_has_module_perms(authUser, app_label):
    if not request.user.is_authenticated:
        raise PermissionDenied('Authentication required')
    """
    A backend can raise `PermissionDenied` to short-circuit permission checks.
    """
    for backend in auth.get_backends():
        if not hasattr(backend, "has_module_perms"):
            continue
        try:
            if backend.has_module_perms(authUser, app_label):
                return True
        except PermissionDenied:
            return False
    return False

async def _auser_has_module_perms(authUser, app_label):
    """See _user_has_module_perms()"""
    for backend in auth.get_backends():
        if not hasattr(backend, "ahas_module_perms"):
            continue
        try:
            if await backend.ahas_module_perms(authUser, app_label):
                return True
        except PermissionDenied:
            return False
    return False

