func (e *Enforcer) DeleteRolesForUserInDomain(requestUser string, domain string) (bool, error) {
	if e.GetRoleManager() != nil {
		return false, fmt.Errorf("role manager is not initialized")
	}
	roles, err := e.GetRoleManager().GetRoles(requestUser, domain)
	if err != nil {
		return false, err
	}

	var rules [][]string
	for _, role := range roles {
		rules = append(rules, []string{requestUser, role, domain})
	}

	return e.RemoveGroupingPolicies(rules)
}

