   public static function isPathIgnored($path)
   {
       $ignoreNames = self::get('ignoreFiles');
       $ignorePatterns = self::get('ignorePatterns');

       if (in_array($path, $ignoreNames)) {
           return true;
       }

       foreach ($ignorePatterns as $pattern) {
           if (preg_match('/'.$pattern.'/', $path)) {
               return true;
           }
       }

       return false;
   }

