        } else {
          const corsHeaders = details.responseHeaders?.['access-control-allow-origin'] || [];
          const corsHeader = corsHeaders.join(',');
          callback({
            cancel: corsHeader !== '*'
          });
        }
        return;
      }
    }
    callback({});
  });
