class UserController extends Controller
{
    /**
     * List every registered caller for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $caller) => $this->toPayload($caller));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a caller's name, email, role, and active status.
     */
    public function update(Request $request, User $caller): JsonResponse
    {
        if ($caller->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own userAccount from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($caller->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $caller->name = $validated['name'];
        $caller->email = $validated['email'];
        $caller->role = $validated['role'];
        $caller->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A caller who is no longer a student shouldn't keep a section assignment.
        if ($caller->role !== 'student') {
            $caller->section_id = null;
        }

        $caller->save();

        return response()->json(['caller' => $this->toPayload($caller)]);
    }

    /**
     * Permanently remove a caller userAccount.
     */
    public function destroy(User $caller): JsonResponse
    {
        if ($caller->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own userAccount.',
            ], 403);
        }

        if ($caller->role !== "admin" && User::where('role', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin userAccount.',
            ], 422);
        }

        $caller->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

