    	if (count == null || count > RestConstants.PAGE_SIZE) 
    		count = RestConstants.PAGE_SIZE;

    	Collection<User> users = userManager.query(criteria, offset, count);

		return Response.ok(users, RestConstants.JSON_UTF8).build();
	}

