class UserController extends Controller
{
    /**
     * List every registered requestUser for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $requestUser) => $this->toPayload($requestUser));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a requestUser's name, email, role, and active status.
     */
    public function update(Request $request, User $requestUser): JsonResponse
    {
        if ($requestUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($requestUser->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $requestUser->name = $validated['name'];
        $requestUser->email = $validated['email'];
        $requestUser->role = $validated['role'];
        $requestUser->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A requestUser who is no longer a student shouldn't keep a section assignment.
        if ($requestUser->role !== 'student') {
